def last_index(items):
    if not items:
        return -1
    return len(items) - 1

def chunk(items, size):
    """Split items into consecutive lists of at most `size` elements."""
    result = []
    for i in range(0, len(items), size):
        result.append(items[i:i + size])
    return result

def median(numbers):
    """Return the median of a non-empty list of numbers (mean of the middle two when even)."""
    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    if n % 2 == 1:
        return sorted_numbers[n // 2]
    else:
        mid1 = sorted_numbers[n // 2 - 1]
        mid2 = sorted_numbers[n // 2]
        return (mid1 + mid2) / 2

def truncate(text, limit):
    """Return text unchanged when it fits in `limit` characters, otherwise cut it
    and end with an ellipsis so the result is exactly `limit` characters long."""
    if len(text) <= limit:
        return text
    else:
        return text[:limit - 3] + '...'

def count_words(text):
    """Return the number of whitespace-separated words; an empty or blank string has none."""
    return len(text.split())

def is_leap(year):
    """True when the year is a leap year in the Gregorian calendar."""
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

def percent(part, whole):
    """Return part as a percentage of whole, rounded to one decimal; 0.0 when whole is 0."""
    if whole == 0:
        return 0.0
    return round((part / whole) * 100, 1)

def dedupe(items):
    """Remove duplicates, keeping the first occurrence and the original order."""
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def clip_index(index, length):
    if index < 0:
        return length + index
    else:
        return min(max(index, 0), length - 1)

def balanced(text):
    count = 0
    for char in text:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
            if count < 0:
                return False
    return count == 0

def average_or_zero(numbers):
    """Return the mean, or 0 when the list is empty."""
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)
